ALTER TABLE public.visits ADD COLUMN operational_on date;
UPDATE public.visits SET operational_on=date::date WHERE date ~ '^\d{4}-\d{2}-\d{2}$' AND status NOT IN('finalizada','cancelada');
CREATE FUNCTION public.set_operational_day() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (TG_OP='INSERT' OR NEW.date IS DISTINCT FROM OLD.date) AND NEW.date ~ '^\d{4}-\d{2}-\d{2}$' THEN NEW.operational_on:=NEW.date::date;END IF;RETURN NEW;END $$;
CREATE TRIGGER visit_operational_day BEFORE INSERT OR UPDATE ON public.visits FOR EACH ROW EXECUTE FUNCTION public.set_operational_day();
CREATE TABLE public.visit_supply_requirements(visit_id text NOT NULL REFERENCES public.visits(id) ON DELETE CASCADE,item_id text NOT NULL REFERENCES public.inventory_items(id),qty integer NOT NULL CHECK(qty>0),PRIMARY KEY(visit_id,item_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.visit_supply_requirements TO authenticated;GRANT ALL ON public.visit_supply_requirements TO service_role;ALTER TABLE public.visit_supply_requirements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "supply requirements read" ON public.visit_supply_requirements FOR SELECT TO authenticated USING(public.can_access_field_visit(visit_id));
CREATE POLICY "supply requirements configure" ON public.visit_supply_requirements FOR ALL TO authenticated USING(public.is_ops(auth.uid()) AND EXISTS(SELECT 1 FROM public.visits v WHERE v.id=visit_id AND v.status NOT IN('finalizada','cancelada'))) WITH CHECK(public.is_ops(auth.uid()) AND EXISTS(SELECT 1 FROM public.visits v WHERE v.id=visit_id AND v.status NOT IN('finalizada','cancelada')));
CREATE TABLE public.field_kits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,description text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE ON public.field_kits TO authenticated;GRANT ALL ON public.field_kits TO service_role;ALTER TABLE public.field_kits ENABLE ROW LEVEL SECURITY;
CREATE POLICY "kits read" ON public.field_kits FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));CREATE POLICY "kits configure" ON public.field_kits FOR ALL TO authenticated USING(public.is_ops(auth.uid())) WITH CHECK(public.is_ops(auth.uid()));
CREATE TABLE public.kit_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kit_id uuid NOT NULL REFERENCES public.field_kits(id),visit_id text NOT NULL REFERENCES public.visits(id),staff_id text NOT NULL REFERENCES public.staff_members(id),state text NOT NULL DEFAULT 'assigned' CHECK(state IN('assigned','received','returned')),version integer NOT NULL DEFAULT 1,history jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_live_kit ON public.kit_assignments(kit_id) WHERE state<>'returned';
GRANT SELECT,INSERT,UPDATE ON public.kit_assignments TO authenticated;GRANT ALL ON public.kit_assignments TO service_role;ALTER TABLE public.kit_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "kit assignments read" ON public.kit_assignments FOR SELECT TO authenticated USING(public.is_ops(auth.uid()) OR public.can_access_field_visit(visit_id));CREATE POLICY "kit assignments create" ON public.kit_assignments FOR INSERT TO authenticated WITH CHECK(public.is_ops(auth.uid()));CREATE POLICY "kit assignments update" ON public.kit_assignments FOR UPDATE TO authenticated USING(staff_id IN(SELECT public.my_staff_ids()));
CREATE FUNCTION public.guard_kit_assignment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_OP='INSERT' THEN IF NOT public.is_ops(auth.uid()) AND auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Solo Coordinación asigna kits';END IF; IF NOT EXISTS(SELECT 1 FROM public.visits v WHERE v.id=NEW.visit_id AND v.status NOT IN('cancelada','finalizada') AND (v.staff_id=NEW.staff_id OR EXISTS(SELECT 1 FROM public.visit_participants p WHERE p.visit_id=v.id AND p.staff_id=NEW.staff_id AND p.active))) THEN RAISE EXCEPTION 'Asigna el kit a un participante de la visita';END IF;NEW.state:='assigned';NEW.version:=1;NEW.history:=jsonb_build_array(jsonb_build_object('state','assigned','actor',auth.uid(),'at',now()));
 ELSE IF NEW.kit_id<>OLD.kit_id OR NEW.visit_id<>OLD.visit_id OR NEW.staff_id<>OLD.staff_id OR NEW.staff_id NOT IN(SELECT public.my_staff_ids()) OR NEW.version<>OLD.version+1 OR NOT ((OLD.state='assigned' AND NEW.state='received') OR(OLD.state='received' AND NEW.state='returned')) THEN RAISE EXCEPTION 'Paso de kit no permitido';END IF;NEW.history:=OLD.history||jsonb_build_array(jsonb_build_object('state',NEW.state,'actor',auth.uid(),'at',now()));END IF;RETURN NEW;END $$;
CREATE TRIGGER kit_assignment_guard BEFORE INSERT OR UPDATE ON public.kit_assignments FOR EACH ROW EXECUTE FUNCTION public.guard_kit_assignment();
CREATE TABLE public.course_lessons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),course_id text NOT NULL REFERENCES public.courses(id),title text NOT NULL,body text NOT NULL DEFAULT '',position integer NOT NULL DEFAULT 1);
GRANT SELECT,INSERT,UPDATE ON public.course_lessons TO authenticated;GRANT ALL ON public.course_lessons TO service_role;ALTER TABLE public.course_lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY "lessons read" ON public.course_lessons FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));CREATE POLICY "lessons author" ON public.course_lessons FOR ALL TO authenticated USING(public.is_ops(auth.uid())) WITH CHECK(public.is_ops(auth.uid()));
CREATE TABLE public.lesson_completions(user_id uuid NOT NULL DEFAULT auth.uid(),lesson_id uuid NOT NULL REFERENCES public.course_lessons(id),completed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,lesson_id));
GRANT SELECT,INSERT ON public.lesson_completions TO authenticated;GRANT ALL ON public.lesson_completions TO service_role;ALTER TABLE public.lesson_completions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own learning read" ON public.lesson_completions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_ops(auth.uid()));CREATE POLICY "own learning complete" ON public.lesson_completions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.is_staff(auth.uid()));
CREATE OR REPLACE FUNCTION public.field_supplies_ready(_visit text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.visit_supply_requirements r WHERE r.visit_id=_visit AND r.qty>coalesce((SELECT sum(s.qty) FROM public.inventory_reservations s WHERE s.visit_id=_visit AND s.item_id=r.item_id AND s.status IN('reservado','consumido')),0)) $$;
CREATE FUNCTION public.guard_support_supplies() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.support_state='READY' AND OLD.support_state<>'READY' AND NOT public.field_supplies_ready(NEW.visit_id) THEN RAISE EXCEPTION 'Aparta las cantidades requeridas antes de salir';END IF;RETURN NEW;END $$;
CREATE TRIGGER support_supplies_guard BEFORE UPDATE ON public.visit_participants FOR EACH ROW EXECUTE FUNCTION public.guard_support_supplies();
CREATE FUNCTION public.guard_execution_supplies() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.state IN('READY_TO_DEPART','EN_ROUTE') AND NEW.state<>OLD.state AND NOT public.field_supplies_ready(NEW.visit_id) THEN RAISE EXCEPTION 'Aparta las cantidades requeridas antes de salir';END IF;RETURN NEW;END $$;
CREATE TRIGGER execution_supplies_guard BEFORE UPDATE ON public.visit_executions FOR EACH ROW EXECUTE FUNCTION public.guard_execution_supplies();
CREATE OR REPLACE FUNCTION public.reserve_supply(_item text,_visit text,_qty integer,_key text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s integer;r integer;rid uuid;existing public.inventory_reservations%ROWTYPE;expiry text;BEGIN
 IF NOT public.can_access_field_visit(_visit) OR EXISTS(SELECT 1 FROM public.visits WHERE id=_visit AND status IN('cancelada','finalizada')) THEN RAISE EXCEPTION 'No puedes apartar insumos para esta visita';END IF;
 IF _qty IS NULL OR _qty<=0 OR coalesce(btrim(_key),'')='' THEN RAISE EXCEPTION 'Cantidad o clave inválida';END IF;
 SELECT stock,expires INTO s,expiry FROM public.inventory_items WHERE id=_item FOR UPDATE;IF s IS NULL THEN RAISE EXCEPTION 'Insumo no encontrado';END IF;
 IF expiry ~ '^\d{4}-\d{2}-\d{2}$' THEN IF expiry::date<current_date THEN RAISE EXCEPTION 'Lote vencido';END IF;END IF;
 SELECT * INTO existing FROM public.inventory_reservations WHERE idempotency_key=_key;IF existing.id IS NOT NULL THEN IF existing.item_id<>_item OR existing.visit_id IS DISTINCT FROM _visit OR existing.qty<>_qty THEN RAISE EXCEPTION 'La clave corresponde a otra reserva';END IF;RETURN existing.id;END IF;
 SELECT coalesce(sum(qty),0) INTO r FROM public.inventory_reservations WHERE item_id=_item AND status='reservado';IF s-r<_qty THEN RAISE EXCEPTION 'No hay existencias disponibles suficientes';END IF;
 INSERT INTO public.inventory_reservations(item_id,visit_id,qty,idempotency_key,created_by) VALUES(_item,_visit,_qty,_key,auth.uid()) RETURNING id INTO rid;RETURN rid;END $$;
CREATE OR REPLACE FUNCTION public.settle_reservation(_id uuid,_consume boolean) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rec public.inventory_reservations%ROWTYPE;BEGIN SELECT * INTO rec FROM public.inventory_reservations WHERE id=_id FOR UPDATE;IF rec.id IS NULL OR NOT public.can_access_field_visit(rec.visit_id) THEN RAISE EXCEPTION 'No tienes acceso a esta reserva';END IF;IF rec.status<>'reservado' THEN RETURN rec.status;END IF;IF _consume THEN UPDATE public.inventory_items SET stock=stock-rec.qty WHERE id=rec.item_id AND stock>=rec.qty;IF NOT FOUND THEN RAISE EXCEPTION 'Existencias insuficientes';END IF;END IF;UPDATE public.inventory_reservations SET status=CASE WHEN _consume THEN 'consumido' ELSE 'liberado' END,updated_at=now() WHERE id=_id;RETURN CASE WHEN _consume THEN 'consumido' ELSE 'liberado' END;END $$;
DROP POLICY "reservations read" ON public.inventory_reservations;CREATE POLICY "reservations read" ON public.inventory_reservations FOR SELECT TO authenticated USING(public.can_access_field_visit(visit_id));
CREATE OR REPLACE FUNCTION public.guard_aux_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF NOT public.is_aux_only(auth.uid()) THEN RETURN NEW;END IF;
 IF NEW.scope<>'staff' OR NEW.kind NOT IN('nota_campo','checklist','borrador_tarea','cobro_campo','handover','cierre_jornada','solicitud_ayuda','mensaje') THEN RAISE EXCEPTION 'Registro fuera de las funciones del auxiliar';END IF;
 IF NEW.kind IN('nota_campo','checklist','borrador_tarea','cobro_campo') AND NEW.ref_id IS NOT NULL AND NOT public.can_access_field_visit(NEW.ref_id) THEN RAISE EXCEPTION 'Solo puedes registrar acciones de tus visitas';END IF;
 IF TG_OP='UPDATE' AND (NEW.kind<>OLD.kind OR NEW.scope<>OLD.scope OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.ref_id IS DISTINCT FROM OLD.ref_id) THEN RAISE EXCEPTION 'No puedes cambiar la identidad del registro';END IF;
 IF NEW.kind='handover' THEN
 IF TG_OP='INSERT' AND (coalesce(NEW.data->>'from','')='' OR NEW.data->>'from' NOT IN(SELECT public.my_staff_ids()) OR NEW.status<>'PENDIENTE_ACEPTACION') THEN RAISE EXCEPTION 'La entrega debe salir de tu perfil';END IF;
 IF TG_OP='UPDATE' AND (coalesce(OLD.data->>'to','')='' OR OLD.data->>'to' NOT IN(SELECT public.my_staff_ids()) OR OLD.status<>'PENDIENTE_ACEPTACION' OR NEW.status NOT IN('ACEPTADO','RECHAZADO') OR (NEW.data-'status'-'answeredAt') IS DISTINCT FROM (OLD.data-'status'-'answeredAt') OR NEW.title<>OLD.title OR NEW.detail<>OLD.detail) THEN RAISE EXCEPTION 'Solo quien recibe puede responder sin alterar los pendientes';END IF;END IF;RETURN NEW;END $$;
CREATE FUNCTION public.field_day_pending(_staff text,_day date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb;BEGIN
 IF NOT public.is_ops(auth.uid()) AND _staff NOT IN(SELECT public.my_staff_ids()) THEN RAISE EXCEPTION 'Sin acceso a esta jornada';END IF;
 SELECT coalesce(jsonb_agg(x),'[]') INTO result FROM (
 SELECT v.id,'visita'::text kind,v.service title,true critical FROM public.visits v WHERE (v.operational_on=_day OR v.operational_on IS NULL) AND v.status NOT IN('finalizada','cancelada') AND ((v.staff_id=_staff AND NOT EXISTS(SELECT 1 FROM public.visit_executions e WHERE e.visit_id=v.id AND e.state IN('SERVICE_FINISHED','ADMINISTRATIVE_REVIEW','ADMINISTRATIVELY_COMPLETED','NOT_PERFORMED'))) OR EXISTS(SELECT 1 FROM public.visit_participants p WHERE p.visit_id=v.id AND p.staff_id=_staff AND p.active AND p.support_state<>'COMPLETED'))
 UNION ALL SELECT t.id,'tarea',t.title,t.critical FROM public.tasks t WHERE t.staff_id=_staff AND NOT t.done AND coalesce(t.stage,'assigned')<>'cancelled' AND (t.due_at IS NULL OR (t.due_at AT TIME ZONE 'America/Bogota')::date<=_day)
 UNION ALL SELECT k.id::text,'kit','Kit pendiente de devolver',true FROM public.kit_assignments k WHERE k.staff_id=_staff AND k.state<>'returned' AND (k.created_at AT TIME ZONE 'America/Bogota')::date<=_day
 ) x;RETURN result;END $$;
CREATE FUNCTION public.guard_field_day_close() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE sid text;day date;pend jsonb;BEGIN
 IF NEW.kind<>'cierre_jornada' THEN RETURN NEW;END IF;
 IF TG_OP='INSERT' THEN
 SELECT id INTO sid FROM public.staff_members WHERE user_id=auth.uid() LIMIT 1;IF sid IS NULL THEN RAISE EXCEPTION 'Vincula tu perfil antes de cerrar';END IF;
 day:=(now() AT TIME ZONE 'America/Bogota')::date;IF NEW.status<>'solicitado' OR NEW.ref_id IS DISTINCT FROM sid||'-'||day::text THEN RAISE EXCEPTION 'El cierre corresponde a tu jornada actual';END IF;
 IF EXISTS(SELECT 1 FROM public.records r WHERE r.kind='cierre_jornada' AND r.ref_id=NEW.ref_id) THEN RAISE EXCEPTION 'El cierre ya fue solicitado';END IF;
 pend:=public.field_day_pending(sid,day);IF EXISTS(SELECT 1 FROM jsonb_array_elements(pend) p WHERE (p->>'critical')::boolean) THEN RAISE EXCEPTION 'Resuelve o transfiere los pendientes críticos';END IF;
 NEW.data:=jsonb_build_object('staffId',sid,'day',day,'pending',pend,'requestedAt',now());
 ELSE
 IF OLD.status<>'solicitado' OR NEW.status<>'verificado' OR NOT public.is_ops(auth.uid()) OR OLD.created_by=auth.uid() THEN RAISE EXCEPTION 'Otro responsable de Coordinación verifica el cierre';END IF;
 IF NEW.data IS DISTINCT FROM OLD.data OR NEW.ref_id IS DISTINCT FROM OLD.ref_id OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN RAISE EXCEPTION 'No se alteran los datos del cierre';END IF;
 sid:=OLD.data->>'staffId';day:=(OLD.data->>'day')::date;IF sid IS NULL OR day IS NULL THEN RAISE EXCEPTION 'Este cierre antiguo requiere revisión manual';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(public.field_day_pending(sid,day)) p WHERE (p->>'critical')::boolean) THEN RAISE EXCEPTION 'La jornada tiene pendientes críticos';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER field_day_close_guard BEFORE INSERT OR UPDATE ON public.records FOR EACH ROW EXECUTE FUNCTION public.guard_field_day_close();
REVOKE ALL ON FUNCTION public.set_operational_day(),public.guard_kit_assignment(),public.guard_support_supplies(),public.guard_execution_supplies(),public.guard_field_day_close() FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.field_supplies_ready(text),public.field_day_pending(text,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.field_supplies_ready(text),public.field_day_pending(text,date) TO authenticated,service_role;